from itertools import product, combinations
from collections import Counter


def _route(data, minimum_duration, exact_coupons):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], initial_mask, data["coupons"])
    distance = {start_state: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distance.get(state) != arrival:
            continue
        if (node == data["target"] and mask == full
                and (not exact_coupons or remaining == 0)):
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            duration = edge["duration"]
            outcomes = [(duration, remaining)]
            if remaining:
                discounted = max(minimum_duration,
                                 duration - edge.get("discount", 0))
                outcomes.append((discounted, remaining - 1))
            for travel, next_remaining in outcomes:
                next_time = depart + travel
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if next_time < distance.get(next_state, float("inf")):
                    distance[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask,
                                           next_remaining))
    return {"arrival": None}


def _build_route(minimum_duration, exact_coupons):
    return lambda data: _route(data, minimum_duration, exact_coupons)


def _ledger(data):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (sequence, event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        quotient, remainder = divmod(numerator, 10000)
        if mode == "half_up" and remainder * 2 >= 10000:
            quotient += 1
        return quotient

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}

    choices = []
    for name in names:
        choices.append(sorted(rows[name], reverse=True) + [-1])

    for vector in product(*choices):
        selected = {name: version for name, version in zip(names, vector)
                    if version != -1}
        if any(name not in selected or not low <= selected[name] <= high
               for name, (low, high) in roots.items()):
            continue
        if any(version in blocked.get(name, [])
               or (name in pins and pins[name] != version)
               for name, version in selected.items()):
            continue

        graph = {name: [] for name in selected}
        valid = True
        for name, version in selected.items():
            row = rows[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if (target not in selected
                        or not dep["min"] <= selected[target] <= dep["max"]):
                    valid = False
                    break
                graph[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        # Installed packages must be exactly the dependency closure of roots.
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph.get(name, []))
        if reachable != set(selected):
            continue

        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in graph):
            continue
        return {"versions": selected}
    return {"error": "unsatisfiable"}


def _scheduling(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for subset in combinations(jobs, k):
        ids = [job["id"] for job in subset]
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in subset)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active_ends = []
        valid = True
        for job in sorted(subset, key=lambda item: (item["start"], item["end"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            active_ends.append(job["end"])
            if len(active_ends) > 2:
                valid = False
                break
        if not valid:
            continue

        sorted_ids = sorted(ids)
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value
                or (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


